		}
		// Should show filter info
		if !strings.Contains(output, "Filtered by session:") {
			t.Errorf("expected 'Filtered by session:' in output, got:\n%s", output)
		}
	})

	t.Run("filter by session ID prefix", func(t *testing.T) {
