func buildCondensedCompactTranscript(transcriptBytes []byte) ([]summarize.Entry, error) {
	type compactLine struct {
		V          int             `json:"v"`
		Type       string          `json:"type"`
		Content    json.RawMessage `json:"content"`
		CLIVersion string          `json:"cli_version"`
	}

	type contentBlock struct {
		Type  string                 `json:"type"`
		Text  string                 `json:"text"`
		Name  string                 `json:"name"`
		Input map[string]interface{} `json:"input"`
	}

	lines := strings.Split(strings.TrimSpace(string(transcriptBytes)), "\n")
	entries := make([]summarize.Entry, 0, len(lines))

	for _, rawLine := range lines {
		rawLine = strings.TrimSpace(rawLine)
		if rawLine == "" {
			continue
		}

		var line map[string]json.RawMessage
		if err := json.Unmarshal([]byte(rawLine), &line); err != nil {
			return nil, err
		}

		var version int
		if err := json.Unmarshal(line["v"], &version); err != nil || version == 0 {
			return nil, errors.New("not compact transcript format")
		}

		var cliVersion string
		if err := json.Unmarshal(line["cli_version"], &cliVersion); err != nil || cliVersion == "" {
			return nil, errors.New("not compact transcript format")
		}

		var lineType string
		if err := json.Unmarshal(line["type"], &lineType); err != nil || lineType == "" {
			continue
		}

		var blocks []map[string]json.RawMessage
		if contentJSON, ok := line["content"]; ok && len(contentJSON) > 0 {
			if err := json.Unmarshal(contentJSON, &blocks); err != nil {
				continue
			}
		}

		switch lineType {
		case string(summarize.EntryTypeUser):
			var parts []string
			for _, block := range blocks {
				var text string
				if err := json.Unmarshal(block["text"], &text); err == nil && text != "" {
					parts = append(parts, text)
				}
			}
			if len(parts) > 0 {
				entries = append(entries, summarize.Entry{Type: summarize.EntryTypeUser, Content: strings.Join(parts, "\n")})
			}

		case string(summarize.EntryTypeAssistant):
			for _, block := range blocks {
				var blockType string
				_ = json.Unmarshal(block["type"], &blockType)
				switch blockType {
				case "text":
					var text string
					if err := json.Unmarshal(block["text"], &text); err == nil && text != "" {
						entries = append(entries, summarize.Entry{Type: summarize.EntryTypeAssistant, Content: text})
					}
				case "tool_use":
					var toolName string
					_ = json.Unmarshal(block["name"], &toolName)

					var input map[string]interface{}
					if inputJSON, ok := block["input"]; ok && len(inputJSON) > 0 {
						_ = json.Unmarshal(inputJSON, &input)
					}

					entries = append(entries, summarize.Entry{
						Type:       summarize.EntryTypeTool,
						ToolName:   toolName,
						ToolDetail: extractToolDetailForExplain(input),
					})
				}
			}
		}
	}

	if len(entries) == 0 {
		return nil, errors.New("no parseable compact transcript entries")
	}

	return entries, nil
}

func extractToolDetailForExplain(input map[string]interface{}) string {
	for _, key := range []string{"description", "command", "file_path", "filePath", "path", "pattern"} {
		if v, ok := input[key].(string); ok && v != "" {
			return v
		}
	}
	return ""
}

