	text := textutil.StripIDEContextTags(geminiContentText(msg.Content))
	if text == "" {
		return
	}

	b, err := json.Marshal([]userTextBlock{{Text: text}})
	if err != nil {
		return
	}

	line := base
	line.Type = transcript.TypeUser
	line.TS = ts
	line.Content = b
	appendLine(result, line)
}

